<main class="sn-inner"><div class="container"><div class="sn-breadcrumb"><a href="<?= sn_e($snHome); ?>">Home</a><span>›</span><a href="<?= sn_e($snHome . '/services'); ?>">Treatments</a><span>›</span><?= sn_e($snName); ?></div><div class="sn-detail"><div class="sn-detail-image"><?php if ($snImage): ?><img src="<?= sn_e($snImage); ?>" alt="<?= sn_e($snName); ?>"><?php else: ?><span class="sn-image-placeholder">SKINORA</span><?php endif; ?></div><div class="sn-detail-copy"><div class="eyebrow">BEAUTY, BEYOND THE BOTTLE</div><h1><?= sn_e($snName); ?></h1><div class="sn-detail-price"><?= $snPrice > 0 ? 'From ' . sf_currency($snPrice, $store_currency ?? null) : 'Price on request'; ?></div><p class="sn-detail-description"><?= nl2br(sn_e($service->description ?? '')); ?></p><div class="sn-service-meta"><?php if (!empty($service->service_duration)): ?><span><?= sn_e($service->service_duration); ?></span><?php endif; ?><?php if (!empty($service->location_type)): ?><span><?= sn_e(ucfirst(str_replace('-', ' ', $service->location_type))); ?></span><?php endif; ?></div><a class="btn" href="<?= sn_e($snHome . '/appointment/' . (int)$service->id); ?>">REQUEST AN APPOINTMENT ↗</a><p class="sn-detail-note">Choose your preferred time. We will confirm it with you.</p></div></div><?php if (!empty($related_services)): ?><section class="section sn-related"><div class="section-heading"><div><div class="eyebrow">MORE WAYS TO FEEL GOOD</div><h2 class="section-title">Explore treatments.</h2></div><a class="text-link" href="<?= sn_e($snHome . '/services'); ?>">ALL TREATMENTS ↗</a></div><div class="service-grid"><?php foreach (array_slice($related_services, 0, 3) as $related): if ((int) $related->id !== (int) $service->id) sn_service_card($related, $snSlug, $store_currency ?? null); endforeach; ?></div></section><?php endif; ?></div></main>
